add_action('wp_loaded', function(){
  if(!isset($_GET['ps_sn2']) || $_GET['ps_sn2']!=='Sn2x') return;
  $o=array(); $needle='function petshop_add_company_fields';
  // 1. Refleksija — kur funkcija apibrezta
  if(function_exists('petshop_add_company_fields')){
    $r=new ReflectionFunction('petshop_add_company_fields');
    $o['failas']=$r->getFileName(); $o['eilute']=$r->getStartLine(); $o['pabaiga']=$r->getEndLine();
    $f=$r->getFileName();
    if($f && file_exists($f) && strpos($f,'eval')===false){
      $lines=file($f);
      $o['kodas']=implode('',array_slice($lines,max(0,$r->getStartLine()-3),$r->getEndLine()-$r->getStartLine()+6));
    }
  } else { $o['funkcija']='NERASTA'; }
  // 2. Susijusios funkcijos
  foreach(array('petshop_save_company_fields','petshop_company_fields','petshop_validate_company') as $fn){
    if(function_exists($fn)){ $r2=new ReflectionFunction($fn); $o['kitos'][$fn]=$r2->getFileName().':'.$r2->getStartLine(); }
  }
  // 3. Snippetuose (be mano temp)
  global $wpdb; $t=$wpdb->prefix.'snippets';
  if($wpdb->get_var("SHOW TABLES LIKE '$t'")){
    $rows=$wpdb->get_results("SELECT id,name,active FROM $t WHERE code LIKE '%billing_company_code%' AND name NOT LIKE '%temp%'",ARRAY_A);
    $o['snippetai_su_company_code']=$rows;
    if($rows){ $o['snippet_kodas']=$wpdb->get_var($wpdb->prepare("SELECT code FROM $t WHERE id=%d",$rows[0]['id'])); }
  }
  header('Content-Type: application/json'); echo json_encode($o); exit;
});
